import type {
  FileComponentData,
  UpdateEntityFileSelectFunc,
  UpdateEntityFileUploadFunc,
} from './../ricos-content/index.js';
import type { PluginServices } from './../ricos-plugins/editor-plugins.js';
import type { UploadFn } from './../ricos-types/index.js';
import { getHighestQualityVideo } from './/get-highest-quality-video.js';
import { getMediaFileType } from './/get-media-file-type.js';
import { getUploadError } from './/get-upload-error.js';
import { logInvariant } from './/log-invariant.js';
import { createOpenMediaManagerFn } from './/media-manager/create-open-media-manager-fn.js';
import type { SDKFileMedia } from './/media-manager/types.js';
import { MediaManagerMediaType } from './/media-manager/types.js';
import type { PickMediaFn } from './/media/pick-media.js';
import type { PickMediaFileData, PublicPickMedia } from './/media/public-pick-media.js';
import type { Attachment } from './/pm-node-types.js';
import type { MediaPrivacy } from './/request-service-provider/consts.js';
import { createUploadFn } from './/request-service-provider/media-manager-uploader.js';
import type {
  MediaManagerSDKError,
  RawFileData,
} from './/request-service-provider/upload-types.js';
import { unreachable } from './/uncreachable.js';
import { upload } from './/upload/upload.js';
import { withFileSizeLimitation } from './/with-file-size-limitation.js';
import { uuid } from './../wix-rich-content-common/index.js';

const ACCEPT_MIME_TYPES = 'image/png,image/jpeg,text/csv,text/plain';

type FileUploadCallbacks = {
  onLoadingStart: (attachment: Extract<Attachment, { status: 'loading' }>) => void;
  onSuccess: (attachmentId: string, attachment: Extract<Attachment, { status: 'ok' }>) => void;
  onError: (attachmentId: string, attachment: Extract<Attachment, { status: 'error' }>) => void;
};

export const handleFileUpload = async ({
  services,
  callbacks,
  pluginId,
}: {
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'wixInstance' | 'editorProps' | 'modals'
  >;
  callbacks: FileUploadCallbacks;
  pluginId: string;
}): Promise<void> => {
  const onFileSelected = createOnFileSelectedFn(services, 'public');
  const pickMedia = getFilePickMedia({ services, onFileSelected });

  const result = await pickMedia({
    mimeType: ACCEPT_MIME_TYPES,
    multiple: false,
  });

  switch (result.type) {
    case 'ready-media': {
      const data = result.media;
      const fileData = data[0] as FileComponentData | PickMediaFileData;
      const attachment = fileDataToAttachment(fileData, uuid());
      callbacks.onSuccess(attachment.id, attachment);
      return;
    }
    case 'file': {
      const _file = result.file[0];
      const file = new File([_file], _file.name, { type: _file.type });
      const trackBi = services.uploadService.trackUploadBi(pluginId, file.size, file.name);
      const attachmentId = uuid();

      try {
        const { name } = file;
        const type = name.split('.').pop() || '';

        callbacks.onLoadingStart({
          id: attachmentId,
          status: 'loading',
          file: {
            name,
            type: toFileType(type),
          },
        });

        trackBi?.start();
        const uploadFn = result.customUploadFn || onFileSelected;

        if (!uploadFn) {
          logInvariant(Error('No upload function provided'));
          throw new Error('No upload function provided');
        }

        const uploadedFile = await upload(uploadFn, file);
        const uploadData = uploadedFile.data as FileComponentData;

        const successAttachment = fileDataToAttachment(uploadData, attachmentId);
        callbacks.onSuccess(attachmentId, successAttachment);
        trackBi?.success();
      } catch (error: any) {
        callbacks.onError(attachmentId, {
          id: attachmentId,
          status: 'error',
          file: {
            name: file.name,
            type: toFileType(file.name.split('.').pop() || ''),
          },
          error: error.message || 'Upload failed',
        });
        trackBi?.error(error);
      }
      return;
    }
    case 'cancel': {
      services.modals.notifyExternalModalClosed();
      return;
    }
    default: {
      console.error(unreachable(result));
    }
  }
};

const getFilePickMedia = function ({
  services,
  onFileSelected,
}: {
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'wixInstance' | 'editorProps' | 'modals'
  >;
  onFileSelected: UploadFn | undefined;
}): PickMediaFn | PublicPickMedia['pickFile'] {
  const devPickMedia = services.devService().pickMedia;
  const editorPickMedia = services.editorProps.pickMedia?.pickFile;
  const handleFileSelection =
    services.devService().handleFileSelection ?? createHandleFileSelectionFn(services);

  return devPickMedia
    ? devPickMedia
    : editorPickMedia
      ? editorPickMedia
      : handleFileSelection
        ? async () => {
            try {
              const data = await new Promise<FileComponentData[] | FileComponentData>(
                (resolve, reject) => handleFileSelection(({ data }) => resolve(data), reject)
              );
              return { type: 'ready-media' as const, media: data instanceof Array ? data : [data] };
            } catch {
              return { type: 'cancel' as const };
            }
          }
        : async ({ mimeType }: Parameters<PickMediaFn>[0]) => {
            const files =
              (await services.uploadService?.selectFiles({ accept: mimeType, multiple: false })) ??
              [];
            return { type: 'file' as const, file: files, customUploadFn: onFileSelected };
          };
};

const isPickMediaFileType = (
  data: (FileComponentData & { url?: string }) | PickMediaFileData
): data is PickMediaFileData => 'type' in data && data.type === 'file';

const fileDataToAttachment = (
  fileData: (FileComponentData & { url?: string }) | PickMediaFileData,
  attachmentId?: string
): Extract<Attachment, { status: 'ok' }> => {
  if (isPickMediaFileType(fileData)) {
    const fileType = toFileType(fileData.extension || '');
    const fileUrl = ('url' in fileData.src ? fileData.src.url : fileData.src.id) || '';

    return {
      id: attachmentId || fileUrl,
      status: 'ok',
      file: {
        name: fileData.name || '',
        type: fileType,
        url: fileUrl,
      },
    };
  }

  const fileName =
    ('original_file_name' in fileData && fileData.original_file_name) ||
    ('file_name' in fileData && (fileData as any).file_name) ||
    ('name' in fileData && fileData.name) ||
    '';

  const fileExtension = fileName.split('.').pop() || ('type' in fileData && fileData.type) || '';

  const fileType = toFileType(fileExtension);

  // URL can be in url, id, or file_name fields
  const fileUrl = fileData.url || fileData.id || '';

  return {
    id: attachmentId || fileUrl,
    status: 'ok',
    file: {
      name: fileName,
      type: fileType,
      url: fileUrl,
    },
  };
};

const createOnFileSelectedFn = (
  services: Pick<PluginServices, 'devService' | 'uploadService' | 'wixInstance' | 'editorProps'>,
  privacy: MediaPrivacy = 'public'
) => {
  const { metaSiteId, uid, siteOwnerId } = services.wixInstance();

  if (!metaSiteId) {
    return undefined;
  }

  const fileUpload = (file: File, updateEntity: UpdateEntityFileUploadFunc<FileComponentData>) => {
    const upload = createUploadFn(services);
    const fileType = getMediaFileType(file.name);
    return upload(file, fileType, { privacy })
      .then(({ original_file_name: name, media_type, file_url, file_output }: RawFileData) => {
        const fileUrl = file_output?.video
          ? getHighestQualityVideo(file_output.video).url
          : file_url;
        const type = file.name.split('.').length > 1 ? file.name.split('.').pop() : media_type;
        const componentData = getFilePluginComponentData(name, fileUrl, type || '', privacy);
        updateEntity({ data: componentData });
      })
      .catch((error: MediaManagerSDKError) => {
        const isOwner = siteOwnerId === uid;
        const mediaUploadError = getUploadError(error, metaSiteId, isOwner);
        updateEntity({ error: mediaUploadError });
      });
  };

  return withFileSizeLimitation(fileUpload, services.editorProps.fileUploadSizeLimit);
};

const createHandleFileSelectionFn = (services: Pick<PluginServices, 'wixInstance' | 'modals'>) => {
  const openMediaManager = createOpenMediaManagerFn(services.modals);
  if (!openMediaManager) {
    return undefined;
  }
  return (
    updateEntity: UpdateEntityFileSelectFunc<FileComponentData[] | FileComponentData>,
    onCancel: () => void
  ) =>
    openMediaManager({
      mediaType: MediaManagerMediaType.ALL_MEDIA,
      appDefId: services.wixInstance().appDefId,
    })
      .then(items => {
        const componentData = getFilePluginComponentDataFromMediaManager(items[0]);
        updateEntity({ data: [componentData] });
      })
      .catch(onCancel);
};

const getFilePluginComponentDataFromMediaManager = (file: SDKFileMedia) => {
  const { title: name, fileUrl, fileName, fileSize: size } = file;
  let url = fileUrl;
  let type = (fileName.split('.').length === 1 ? name : fileName).split('.').pop();
  if (file.mediaType === 'video') {
    const video = getHighestQualityVideo(file.fileOutput.video);
    url = video.url;
    type = video.format;
  }
  if (!type) {
    type = 'unknown';
    console.error('could not determine file type for file:', file);
  }
  return getFilePluginComponentData(name, url, type, 'public', size);
};

const getFilePluginComponentData = (
  name: string,
  fileUrl: string,
  type: string,
  privacy: MediaPrivacy = 'public',
  size?: number
): FileComponentData => {
  const componentData = {
    name,
    type,
    id: fileUrl,
    privacy,
  };
  return size ? { ...componentData, size } : componentData;
};

const toFileType = (type: string): Attachment['file']['type'] => {
  if (type.includes('image') || type === 'jpeg' || type === 'jpg' || type === 'png') {
    return type === 'jpeg' ? 'jpeg' : type === 'jpg' ? 'jpg' : 'png';
  }

  if (type.includes('csv')) {
    return 'csv';
  }

  if (type.includes('pdf')) {
    return 'pdf';
  }

  return 'text';
};
