import React from 'react';

import type { RicosEditorProps } from './../ricos-common/index.js';
import type { Helpers } from './../ricos-types/editor-types.js';

import { createContext, useContext, useContextSelector } from './use-context-selector.js';

type SomeEditorPropsContextProps = Pick<
  RicosEditorProps,
  | 'visitorUploads'
  | 'fileUploadSizeLimit'
  | 'biSettings'
  | 'pickMedia'
  | 'generalLinkSettings'
  | 'historySettings'
  | 'iframeSandboxDomain'
  | 'instance'
> & { helpers?: Helpers };

export const SomeEditorPropsContext = createContext<SomeEditorPropsContextProps>({});

export const SomeEditorPropsContextProvider: React.FC<
  SomeEditorPropsContextProps & {
    children: React.ReactNode;
  }
> = ({
  children,
  visitorUploads,
  fileUploadSizeLimit,
  biSettings,
  pickMedia,
  generalLinkSettings,
  historySettings,
  helpers,
  iframeSandboxDomain,
  instance,
}) => {
  return (
    <SomeEditorPropsContext.Provider
      value={React.useMemo(
        () => ({
          visitorUploads,
          fileUploadSizeLimit,
          biSettings,
          pickMedia,
          generalLinkSettings,
          helpers,
          historySettings,
          iframeSandboxDomain,
          instance,
        }),
        [
          visitorUploads,
          fileUploadSizeLimit,
          biSettings,
          pickMedia,
          generalLinkSettings,
          historySettings,
          helpers,
          iframeSandboxDomain,
          instance,
        ]
      )}
    >
      {children}
    </SomeEditorPropsContext.Provider>
  );
};

// Prefer the selector version to avoid re-renders
export const useEditorProps = () => {
  const context = useContext(SomeEditorPropsContext);
  if (!context) {
    throw new Error('useEditorProps must be used within a SomeEditorPropsContextProvider');
  }
  return context;
};

export const useEditorProp = <T extends unknown>(
  selector: (context: SomeEditorPropsContextProps) => T
): T => {
  const value = useContextSelector(SomeEditorPropsContext, selector, Object.is);
  return value;
};
