import type { ShiftOptions } from '@floating-ui/react-dom';

/** The www-editor top bar. A known constant, not a measurement — nothing to read it off. */
const TOP_BAR_HEIGHT = 131;

/** Gap kept between the floating element and each piece of chrome. */
const GAP = 16;

/**
 * How much of the viewport `el` covers, measured inward from the edge it hugs.
 *
 * Chrome is measured by where it sits, not by how large its box is. Several of these hooks
 * are stage-spanning hosts that merely *contain* a short bar or panel, so their width/height
 * says nothing about what they occupy — and reserving a host's full extent asks for more room
 * than the viewport has, at which point floating-ui's `shift` stops nudging and collapses to
 * the padding origin. An element that reaches past the far edge of the content area is one of
 * those hosts, and reserves nothing.
 */
const edgeInset = (el: HTMLElement | null, edge: 'bottom' | 'left' | 'right'): number => {
  if (!el) {
    return 0;
  }
  const { top, left, right } = el.getBoundingClientRect();
  if (edge === 'bottom') {
    // Bottom chrome reaching up into the top bar is a full-stage host, not a bar.
    return top <= TOP_BAR_HEIGHT ? 0 : Math.max(0, window.innerHeight - top);
  }
  if (edge === 'left') {
    return right >= window.innerWidth ? 0 : Math.max(0, right);
  }
  return left <= 0 ? 0 : Math.max(0, window.innerWidth - left);
};

// Shared floating-ui `shift` padding for wixel inline-AI floating UI (the prompt modal and the
// selection tooltip). Keeps the floating element clear of the editor chrome by reserving space
// around the viewport: the right AI panel, the left add sidebar, and the bottom drawer +
// toolbar. The chrome is www-editor platform DOM, read by data-hook; missing elements fall
// back to the bare gap so the padding degrades gracefully outside the full wixel editor.
export const getWixelShiftPadding = (): ShiftOptions => {
  const query = (selector: string) => document.querySelector(selector) as HTMLElement | null;

  const aiPanel = query('[data-hook~="ai-assistant-chat__base"]');
  const aiPanelContainer = query('[data-hook~="editor-ai-chat-wrapper"]');
  const addSidebar = query('[data-hook~="add-sidebar-root"]');
  const drawerWrapper = query('[data-hook~="drawer-wrapper"]');
  const workspaceToolbar = query('[data-hook~="workspace-toolbar"]');

  // Union, not sum: an inset already runs to the viewport's bottom edge, so whichever piece
  // starts higher up subsumes the other.
  const bottomChrome = Math.max(
    edgeInset(drawerWrapper, 'bottom'),
    edgeInset(workspaceToolbar, 'bottom')
  );
  // The chat wrapper only stands for the AI panel while the panel itself is mounted.
  const rightChrome = aiPanel ? edgeInset(aiPanelContainer, 'right') : 0;

  // Nothing measurable at the bottom — the hooks are either absent (outside the full wixel
  // editor) or resolved to full-stage hosts. Fall back to the bare bar heights.
  const measuredBottom = bottomChrome > 0 ? bottomChrome + GAP : aiPanel ? 80 : 108;

  return {
    crossAxis: true,
    padding: {
      // Never scaled down to make room for the other sides. The top bar's height is the one
      // boundary here that is known rather than measured, and the one the prompt is most
      // visibly wrong against — so when the sides can't all be satisfied it is the measured
      // bottom that gives. Past even that, `shift` clamps with `max(min, min(value, max))`
      // and so collapses to this origin, parking the prompt just below the bar, in view.
      top: TOP_BAR_HEIGHT,
      bottom: Math.min(measuredBottom, Math.max(0, window.innerHeight - TOP_BAR_HEIGHT)),
      left: edgeInset(addSidebar, 'left') + GAP,
      right: rightChrome + GAP,
    },
  };
};
