import { IconButton } from '@wix/design-system';
import { Add, ArrowRight, Stop } from '@wix/wix-ui-icons-common/lazy';
import classNames from 'classnames';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';

import { AttachmentBar } from './attachment-bar/attachment-bar.js';
import {
  type PromptInputAreaProps,
  type PromptInputAreaRef,
  useAutoHeight,
  useFocusCallback,
  useKeyboardHandler,
} from './prompt-input-area-common.js';
import classes from './prompt-input-area-scss.js';

export type { PromptInputAreaProps, PromptInputAreaRef } from './prompt-input-area-common.js';
export { WidgetPromptInputArea } from './widget-prompt-input-area.js';

export const PromptInputArea = React.forwardRef<PromptInputAreaRef, PromptInputAreaProps>(
  (
    {
      busy,
      readonly,
      placeholder,
      maxLength,
      onChange,
      onSubmit,
      onRemoveAttachment,
      value,
      busyValue,
      onCancel,
      dataHook,
      minHeight,
      forceMultiline: forceMultilineProp,
      attachments = [],
      className,
      style,
      presetBarComponent,
      actionBarComponent,
      fileUploadFn,
    },
    ref
  ) => {
    const { t } = useContext(RicosContext);
    const inputRef = React.useRef<HTMLTextAreaElement>(null);

    const { focus } = useFocusCallback(inputRef);

    React.useImperativeHandle(ref, () => ({ focus }), [focus]);

    const showPresetBar = Boolean(presetBarComponent);
    const allowFileUpload = Boolean(fileUploadFn);
    const showAttachments = allowFileUpload && attachments.length > 0;
    const forceMultiline = forceMultilineProp || showPresetBar || showAttachments || false;

    const { isMultiline, hiddenInputRef } = useAutoHeight({
      inputRef,
      value,
      forceMultiline,
      minHeight,
      baseLineHeight: 24,
    });

    const handleSubmit = React.useCallback(() => {
      if (!value.trim()) {
        return;
      }
      onSubmit();
    }, [value, onSubmit]);

    const { onKeyDown } = useKeyboardHandler({ busy, onEsc: onCancel, onEnter: handleSubmit });
    const displayedValue = busy ? (busyValue ?? t('AIPlugin_Input_Loading_Text')) : value;

    return (
      <div
        className={classNames(
          classes.root,
          {
            [classes.multiline]: isMultiline,
            [classes.forceMultiline]: forceMultiline,
          },
          className
        )}
        style={style}
      >
        {(showPresetBar || showAttachments) && (
          <div className={classes.topBar}>
            {presetBarComponent}
            {showAttachments ? (
              <AttachmentBar attachments={attachments} onRemove={id => onRemoveAttachment?.(id)} />
            ) : null}
          </div>
        )}

        <textarea
          ref={hiddenInputRef}
          className={classNames(classes.textInput, classes.hiddenInput, {
            [classes.forceMultiline]: forceMultiline,
            [classes.allowFileUpload]: allowFileUpload,
          })}
          value={displayedValue}
          readOnly
          aria-hidden
        />
        <textarea
          ref={inputRef}
          data-hook={dataHook}
          name={t(placeholder ?? 'AIPlugin_Input_Placeholder_Text')}
          className={classNames(classes.textInput, {
            [classes.hasTopBar]: showPresetBar || showAttachments,
            [classes.forceMultiline]: forceMultiline,
            [classes.allowFileUpload]: allowFileUpload,
            [classes.disabled]: busy,
          })}
          placeholder={t(placeholder ?? 'AIPlugin_Input_Placeholder_Text')}
          value={displayedValue}
          onChange={e => {
            onChange?.(e.target.value);
          }}
          maxLength={maxLength}
          readOnly={readonly}
          disabled={busy}
          onKeyDown={onKeyDown}
        />
        <div
          className={classNames(classes.actionsContainer, {
            [classes.forceMultiline]: forceMultiline,
            [classes.allowFileUpload]: allowFileUpload,
          })}
        >
          {(allowFileUpload || actionBarComponent) && (
            <div className={classes.actionBar}>
              {allowFileUpload && (
                <IconButton
                  onClick={async () => {
                    await fileUploadFn?.();
                  }}
                  priority="tertiary"
                  skin="dark"
                  disabled={busy}
                >
                  <Add />
                </IconButton>
              )}
              {actionBarComponent}
            </div>
          )}
          <div className={classes.trailing}>
            {busy ? (
              <IconButton onClick={onCancel} priority="secondary">
                <Stop />
              </IconButton>
            ) : (
              <IconButton onClick={handleSubmit} disabled={!value}>
                <ArrowRight />
              </IconButton>
            )}
          </div>
        </div>
      </div>
    );
  }
);

PromptInputArea.displayName = 'PromptInputArea';
