import type { ReferenceType, ShiftOptions } from '@floating-ui/react-dom';
import { autoUpdate, offset, shift, useFloating } from '@floating-ui/react-dom';
import React, { useContext, useEffect, useState } from 'react';

import { RicosContext, ZIndexContext } from './../ricos-context/index.js';
import type { ModalProps } from './../ricos-types/index.js';
import { FocusManager } from './/focus-manager/focus-manager.js';
import { ClickOutside, UiComponentsProvider } from './../ui-components/index.js';

import { getElementScale } from './get-element-scale.js';
import { getWixelShiftPadding } from './get-wixel-shift-padding.js';

/** Inset applied to the container's content box on both sides — see the style block below. */
export const FLOATING_CONTAINER_PADDING_INLINE = 10;

export const FloatingContainer = ({
  children,
  modalConfig,
  state,
  editorContainer,
  onClickOutside,
  fixedWidth,
}: {
  children?: React.ReactNode;
  modalConfig?: ModalProps['modalConfig'];
  state: 'overlay' | 'top';
  editorContainer: HTMLElement;
  onClickOutside: (e: PointerEvent) => void;
  // Overrides the default selection/editor-derived width. Applied as-is: the value is in
  // this container's own layout px — the same coordinate space the `/ scaleX` corrections
  // below resolve the measured defaults into — so it needs no zoom correction of its own.
  // Left undefined by callers that want the default behavior (e.g. the HTML plugin's
  // floating prompt).
  //
  // Deliberately a definite number rather than an intrinsic keyword: `shift` clamps against
  // the box it measures, and this container is `position: fixed`, where an intrinsic width is
  // not clamped by the available space the way `auto`'s shrink-to-fit is. Stating the width
  // keeps what `shift` sees independent of the content.
  fixedWidth?: number;
}) => {
  const { jsdomMode, environment } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);
  const [modalElement, setModalElement] = useState<HTMLDivElement | null>(null);
  const { autoFocus = true, positioning } = modalConfig || {};
  const referenceElement = positioning?.referenceElement as HTMLElement;

  const getShiftOptions = (): ShiftOptions =>
    environment === 'wixel' ? getWixelShiftPadding() : {};

  const middlewares =
    modalConfig?.positioning?.placement === 'bottom'
      ? []
      : [
          offset({
            mainAxis: (referenceElement?.getBoundingClientRect()?.height ?? 0) * -1 - 10,
            crossAxis: 0,
          }),
        ];
  const {
    x,
    y,
    refs: { setReference, setFloating },
    strategy,
  } = useFloating({
    placement: 'bottom-start',
    strategy: 'fixed',
    middleware: [...middlewares, shift(getShiftOptions())],

    whileElementsMounted: (referenceEl, floatingEl, update) =>
      autoUpdate(referenceEl, floatingEl, update, {
        animationFrame: true,
      }),
  });

  useEffect(() => {
    setReference(referenceElement as ReferenceType);
  }, [setReference, referenceElement]);

  const isVisible = jsdomMode || Boolean(x || y) || state === 'top';

  const escToClickOutside = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'Escape') {
      onClickOutside(e as $TSFixMe);
      return;
    }
  };

  const editorRect = editorContainer.getBoundingClientRect();
  const { scaleX } = getElementScale(editorContainer);

  const content = (
    // oxlint-disable-next-line jsx-a11y/no-static-element-interactions
    <div
      ref={ref => {
        setFloating(ref);
        setModalElement(ref);
      }}
      onKeyDown={escToClickOutside}
      style={{
        ...(state === 'top' || modalConfig?.positioning?.placement === 'top'
          ? {
              top: 63,
              left: editorRect.left / scaleX,
              width: fixedWidth ?? editorRect.width / scaleX,
              position: 'fixed',
            }
          : {
              top: y ?? '',
              left: x ?? 0,
              width:
                fixedWidth ??
                (referenceElement?.getBoundingClientRect()?.width
                  ? referenceElement.getBoundingClientRect().width / scaleX
                  : 'auto'),
              position: strategy,
              paddingInline: FLOATING_CONTAINER_PADDING_INLINE,
              boxSizing: 'border-box',
            }),
        zIndex: zIndexService.getZIndex('DIALOG'),
        display: 'block',
        visibility: isVisible ? 'visible' : 'hidden',
        transition: state === 'top' ? 'top 0.2s ease, left 0.2s ease, width 0.2s ease' : undefined,
      }}
    >
      {modalElement && (
        <UiComponentsProvider containerEl={modalElement}>{children}</UiComponentsProvider>
      )}
    </div>
  );

  return (
    <ClickOutside
      onClickOutside={onClickOutside}
      triggerOn={
        typeof modalConfig?.onClickOutside !== 'function'
          ? modalConfig?.onClickOutside?.on
          : undefined
      }
    >
      {autoFocus ? (
        <FocusManager
          focusTrapOptions={{
            returnFocusOnDeactivate: false,
            fallbackFocus: document.activeElement as HTMLElement,
          }}
          jsdomMode={jsdomMode}
          active={isVisible}
          preventScroll
        >
          {content}
        </FocusManager>
      ) : (
        content
      )}
    </ClickOutside>
  );
};
